ee:variables.ee:set-variable:
%dw 2.0
output application/java
import replaceWithValues from modules::utilitaries
var charactersMap={
"<":"&lt;",
">":"&gt;",
"\n":"",
"'":"&quot;",
"xsd\"":"xsd&quot;",
"\"http":"&quot;http"
}
---
replaceWithValues((sizeOf(charactersMap) - 1),write(vars.message,"application/xml"),charactersMap mapObject (item,key,index)->{
(index):{
    "key":(key),
    "value":(item)
}
})
